contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	receive() external payable {}
	fallback() external payable {}

	function check(uint256 amount, address recipient) public {
		require(address(this).balance >= amount);
		(bool okFund, ) = address(c).call{value: amount}("");
		require(okFund);

		uint256 balBefore = address(c).balance;
		(uint256 thisBalBefore) = address(this).balance;

		// non-owner (this test contract) attempts to withdraw all funds
		(bool ok, ) = address(c).call(
			abi.encodeWithSignature("withdrawAll(address)", recipient)
		);

		assert(!ok && address(c).balance == balBefore && address(this).balance == thisBalBefore);
	}
}

